import React, { useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  InputAdornment,
  IconButton,
  Alert,
  CircularProgress
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  Mail,
  Lock
} from '@mui/icons-material';

// Main Login Form Component
const LoginForm = ({ 
  formData, 
  errors, 
  loading, 
  error, 
  onChange, 
  onSubmit, 
  onAutoFill, 
  onTogglePassword 
}) => {
  const [showPassword, setShowPassword] = useState(false);

  const handleChange = (e) => {
    onChange(e);
  };

  const handleSubmit = (e) => {
    onSubmit(e);
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
    onTogglePassword();
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        backgroundColor: '#ffffff',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily: 'system-ui, -apple-system, sans-serif',
      }}
    >
      {/* Left Side - Blue Panel */}
      <Box
        sx={{
          width: { xs: '0%', md: '45%' },
          height: '100vh',
          backgroundColor: '#3b82f6',
          display: { xs: 'none', md: 'flex' },
          alignItems: 'center',
          justifyContent: 'center',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        <Box sx={{ textAlign: 'center', color: 'white', p: 4, zIndex: 1 }}>
          <Typography
            variant="h2"
            sx={{
              fontWeight: 700,
              mb: 2,
              fontSize: '3rem',
              lineHeight: 1.2,
            }}
          >
            Site Survey Tool
          </Typography>
          <Typography
            variant="h5"
            sx={{
              fontWeight: 400,
              mb: 4,
              fontSize: '1.25rem',
              opacity: 0.9,
            }}
          >
            ISP Site Survey Management System
          </Typography>
          <Box
            sx={{
              width: '200px',
              height: '200px',
              backgroundColor: 'rgba(255, 255, 255, 0.1)',
              borderRadius: '50%',
              mx: 'auto',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 4,
            }}
          >
            <Typography variant="h1" sx={{ fontSize: '4rem' }}>📐</Typography>
          </Box>
          <Typography
            variant="body1"
            sx={{
              fontSize: '1.1rem',
              opacity: 0.8,
              maxWidth: '400px',
              mx: 'auto',
            }}
          >
            Professional site survey management for ISP infrastructure
          </Typography>
        </Box>

        {/* Decorative circles */}
        <Box
          sx={{
            position: 'absolute',
            top: '-100px',
            right: '-100px',
            width: '300px',
            height: '300px',
            backgroundColor: 'rgba(255, 255, 255, 0.05)',
            borderRadius: '50%',
          }}
        />
        <Box
          sx={{
            position: 'absolute',
            bottom: '-150px',
            left: '-150px',
            width: '400px',
            height: '400px',
            backgroundColor: 'rgba(255, 255, 255, 0.03)',
            borderRadius: '50%',
          }}
        />
      </Box>

      {/* Right Side - Login Form */}
      <Box
        sx={{
          width: { xs: '100%', md: '55%' },
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          p: 4,
          backgroundColor: '#ffffff',
        }}
      >
        <Box sx={{ width: '100%', maxWidth: '480px' }}>
          {/* Welcome Section */}
          <Box sx={{ textAlign: 'center', mb: 8 }}>
            <Typography
              variant="h3"
              sx={{
                fontWeight: 700,
                color: '#111827',
                mb: 2,
                fontSize: '2rem',
                lineHeight: '2.5rem',
              }}
            >
              Welcome Back
            </Typography>
            <Typography
              variant="body1"
              sx={{
                color: '#6b7280',
                fontSize: '1rem',
                lineHeight: '1.5rem',
              }}
            >
              Sign in to your Site Survey Tool account
            </Typography>
          </Box>

          {/* Login Card */}
          <Box
            sx={{
              backgroundColor: '#ffffff',
              border: '1px solid #e5e7eb',
              borderRadius: '16px',
              p: 8,
              boxShadow: '0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06)',
            }}
          >
            {error && (
              <Alert 
                severity="error" 
                sx={{ 
                  mb: 6,
                  borderRadius: '8px',
                  '& .MuiAlert-message': {
                    fontSize: '0.875rem',
                  }
                }}
              >
                {error}
              </Alert>
            )}

            <Box component="form" onSubmit={handleSubmit} sx={{ width: '100%' }}>
              {/* Email Field */}
              <Box sx={{ mb: 6 }}>
                <Typography
                  component="label"
                  htmlFor="email"
                  sx={{
                    display: 'block',
                    fontSize: '0.875rem',
                    fontWeight: 500,
                    color: '#374151',
                    mb: 2,
                  }}
                >
                  Email Address
                </Typography>
                <Box sx={{ position: 'relative' }}>
                  <Box
                    sx={{
                      position: 'absolute',
                      top: '50%',
                      left: '16px',
                      transform: 'translateY(-50%)',
                      pointerEvents: 'none',
                      zIndex: 1,
                    }}
                  >
                    <Mail sx={{ color: '#9ca3af', fontSize: 20 }} />
                  </Box>
                  <TextField
                    id="email"
                    name="email"
                    type="email"
                    fullWidth
                    value={formData.email}
                    onChange={handleChange}
                    error={!!errors.email}
                    helperText={errors.email}
                    disabled={loading}
                    placeholder="Enter your email"
                    InputProps={{
                      sx: {
                        pl: 5,
                        height: '56px',
                        backgroundColor: '#ffffff',
                        '& .MuiOutlinedInput-root': {
                          borderRadius: '12px',
                          border: '1px solid #d1d5db',
                          '& fieldset': {
                            borderColor: '#d1d5db',
                            borderWidth: '1px',
                          },
                          '&:hover fieldset': {
                            borderColor: '#9ca3af',
                          },
                          '&.Mui-focused fieldset': {
                            borderColor: '#3b82f6',
                            borderWidth: '2px',
                            boxShadow: '0 0 0 3px rgba(59, 130, 246, 0.1)',
                          },
                        },
                      },
                    }}
                  />
                </Box>
              </Box>

              {/* Password Field */}
              <Box sx={{ mb: 6 }}>
                <Typography
                  component="label"
                  htmlFor="password"
                  sx={{
                    display: 'block',
                    fontSize: '0.875rem',
                    fontWeight: 500,
                    color: '#374151',
                    mb: 2,
                  }}
                >
                  Password
                </Typography>
                <Box sx={{ position: 'relative' }}>
                  <Box
                    sx={{
                      position: 'absolute',
                      top: '50%',
                      left: '16px',
                      transform: 'translateY(-50%)',
                      pointerEvents: 'none',
                      zIndex: 1,
                    }}
                  >
                    <Lock sx={{ color: '#9ca3af', fontSize: 20 }} />
                  </Box>
                  <TextField
                    id="password"
                    name="password"
                    type={showPassword ? 'text' : 'password'}
                    fullWidth
                    value={formData.password}
                    onChange={handleChange}
                    error={!!errors.password}
                    helperText={errors.password}
                    disabled={loading}
                    placeholder="Enter your password"
                    InputProps={{
                      sx: {
                        pl: 5,
                        pr: 5,
                        height: '56px',
                        backgroundColor: '#ffffff',
                        '& .MuiOutlinedInput-root': {
                          borderRadius: '12px',
                          border: '1px solid #d1d5db',
                          '& fieldset': {
                            borderColor: '#d1d5db',
                            borderWidth: '1px',
                          },
                          '&:hover fieldset': {
                            borderColor: '#9ca3af',
                          },
                          '&.Mui-focused fieldset': {
                            borderColor: '#3b82f6',
                            borderWidth: '2px',
                            boxShadow: '0 0 0 3px rgba(59, 130, 246, 0.1)',
                          },
                        },
                      },
                      endAdornment: (
                        <InputAdornment position="end" sx={{ mr: 1 }}>
                          <IconButton
                            onClick={togglePasswordVisibility}
                            edge="end"
                            disabled={loading}
                            sx={{ color: '#9ca3af' }}
                          >
                            {showPassword ? <VisibilityOff /> : <Visibility />}
                          </IconButton>
                        </InputAdornment>
                      ),
                    }}
                  />
                </Box>
              </Box>

              {/* Sign In Button */}
              <Button
                type="submit"
                fullWidth
                variant="contained"
                disabled={loading}
                sx={{
                  backgroundColor: '#3b82f6',
                  color: '#ffffff',
                  py: 3,
                  borderRadius: '12px',
                  fontSize: '16px',
                  fontWeight: 600,
                  textTransform: 'none',
                  boxShadow: '0 4px 6px -1px rgba(59, 130, 246, 0.3)',
                  '&:hover': {
                    backgroundColor: '#2563eb',
                    boxShadow: '0 10px 15px -3px rgba(59, 130, 246, 0.4)',
                  },
                  '&:active': {
                    backgroundColor: '#1d4ed8',
                  },
                  '&.Mui-disabled': {
                    backgroundColor: '#e5e7eb',
                    color: '#9ca3af',
                  },
                }}
              >
                {loading ? (
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <CircularProgress size={20} color="inherit" sx={{ mr: 2 }} />
                    Signing in...
                  </Box>
                ) : (
                  'Sign In'
                )}
              </Button>
            </Box>

            {/* Demo Account Section */}
            <Box
              sx={{
                mt: 6,
                p: 4,
                backgroundColor: '#f9fafb',
                border: '1px solid #e5e7eb',
                borderRadius: '12px',
              }}
            >
              <Typography
                variant="body2"
                sx={{
                  color: '#6b7280',
                  mb: 2,
                  fontSize: '0.875rem',
                }}
              >
                Demo Account:
              </Typography>
              <Typography
                variant="body2"
                sx={{
                  color: '#374151',
                  mb: 1,
                  fontFamily: 'monospace',
                  fontSize: '0.813rem',
                }}
              >
                Email: admin@example.com
              </Typography>
              <Typography
                variant="body2"
                sx={{
                  color: '#374151',
                  mb: 3,
                  fontFamily: 'monospace',
                  fontSize: '0.813rem',
                }}
              >
                Password: password
              </Typography>
              <Button
                variant="outlined"
                size="small"
                onClick={() => {
                  onChange({ target: { name: 'email', value: 'admin@example.com' } });
                  onChange({ target: { name: 'password', value: 'password' } });
                }}
                sx={{
                  borderColor: '#3b82f6',
                  color: '#3b82f6',
                  borderRadius: '8px',
                  textTransform: 'none',
                  fontWeight: 500,
                  fontSize: '0.75rem',
                  py: 1,
                  '&:hover': {
                    backgroundColor: '#3b82f6',
                    color: '#ffffff',
                    borderColor: '#3b82f6',
                  },
                }}
              >
                Fill Demo Credentials
              </Button>
            </Box>
          </Box>

          {/* Sign Up Link */}
          <Box sx={{ textAlign: 'center', mt: 6 }}>
            <Typography
              variant="body2"
              sx={{
                color: '#6b7280',
                fontSize: '0.875rem',
              }}
            >
              Don't have an account?{' '}
              <Box
                component="a"
                href="#"
                sx={{
                  color: '#3b82f6',
                  textDecoration: 'none',
                  fontWeight: 600,
                  '&:hover': {
                    textDecoration: 'underline',
                  },
                }}
              >
                Contact administrator
              </Box>
            </Typography>
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export default LoginForm;
